-- Canonical fictional catalog: prototype-fresh/js/data.js; source keys/group/equipment from trainer-library/ru.ts.
begin;

insert into private.exercise_catalog (source_key, name, muscle_group, equipment, measure, bodyweight, aliases, instructions)
select source_key, name, muscle_group, equipment, measure, bodyweight, aliases, instructions
from jsonb_to_recordset($catalog$[
{"source_key":"e0","name":"Приседания со штангой","muscle_group":"Ноги","equipment":"штанга","measure":"reps","bodyweight":false,"aliases":["присед","приседы","Приседания со штангой","barbell full squat"],"instructions":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."]},
{"source_key":"e1","name":"Румынская тяга","muscle_group":"Ноги","equipment":"штанга","measure":"reps","bodyweight":false,"aliases":["румынка","Румынская тяга","barbell romanian deadlift"],"instructions":["Встаньте, поставив ноги на ширине плеч, носки ног направлены вперед.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Согните бедра, сохраняя спину прямой и слегка согнутыми в коленях.","Опустите штангу к земле, держа ее близко к телу.","Почувствуйте растяжение подколенных сухожилий, когда опускаете штангу.","Как только вы почувствуете растяжение подколенных сухожилий, выдвиньте бедра вперед и встаньте прямо.","Напрягите ягодицы в верхней точке движения.","Опустите штангу обратно в исходное положение и повторите желаемое количество повторений."]},
{"source_key":"e2","name":"Жим ногами","muscle_group":"Ноги","equipment":"тренажёр","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e3","name":"Выпады с гантелями","muscle_group":"Ноги","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":["Выпады с гантелями","dumbbell lunge"],"instructions":["Встаньте, ноги на ширине плеч, держа в каждой руке по гантели.","Сделайте шаг вперед правой ногой, опуская тело в положение выпада.","При опускании тела держите спину прямо и грудь вверх.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите с левой ногой.","Чередуйте ноги необходимое количество повторений."]},
{"source_key":"e4","name":"Болгарские выпады","muscle_group":"Ноги","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e5","name":"Ягодичный мост","muscle_group":"Ноги","equipment":"штанга","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e6","name":"Становая тяга","muscle_group":"Спина","equipment":"штанга","measure":"reps","bodyweight":false,"aliases":["становая","Становая тяга","barbell deadlift"],"instructions":["Встаньте, ноги на ширине плеч, положите штангу на землю перед собой.","Согните колени и наклоните бедра, чтобы опустить туловище и взять штангу хватом сверху, руки на расстоянии чуть шире плеч.","Держите спину прямо, а грудь приподнятой, пока вы двигаетесь пятками, чтобы поднять штангу с земли, вытягивая бедра и колени.","Вставая прямо, сожмите ягодицы и держите корпус напряженным.","Опустите штангу обратно на землю, сгибая бедра и колени, сохраняя спину прямой.","Повторите необходимое количество повторений."]},
{"source_key":"e7","name":"Тяга в наклоне","muscle_group":"Спина","equipment":"штанга","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e8","name":"Тяга блока к поясу","muscle_group":"Спина","equipment":"блок","measure":"reps","bodyweight":false,"aliases":["Тяга нижнего блока сидя","cable low seated row"],"instructions":["Сядьте на тренажер, поставьте ноги на подножки и слегка согните колени.","Возьмитесь за рукоятки верхним хватом ладонями вниз.","Держите спину прямо и слегка наклонитесь вперед, сохраняя небольшой изгиб в локтях.","Потяните ручки к телу, сведя лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."]},
{"source_key":"e9","name":"Тяга верхнего блока","muscle_group":"Спина","equipment":"блок","measure":"reps","bodyweight":false,"aliases":["верхний блок"],"instructions":[]},
{"source_key":"e10","name":"Подтягивания","muscle_group":"Спина","equipment":"вес тела","measure":"reps","bodyweight":true,"aliases":["Подтягивания","pull-up"],"instructions":["Повисните на перекладине, повернув ладонями от себя и полностью вытянув руки.","Напрягите корпус и сведите лопатки вместе.","Подтяните тело к перекладине, сгибая локти и приближая грудь к перекладине.","Сделайте паузу в верхней точке движения, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."]},
{"source_key":"e11","name":"Гиперэкстензия","muscle_group":"Спина","equipment":"вес тела","measure":"reps","bodyweight":true,"aliases":[],"instructions":[]},
{"source_key":"e12","name":"Жим лёжа","muscle_group":"Грудь","equipment":"штанга","measure":"reps","bodyweight":false,"aliases":["Жим штанги лёжа","barbell bench press"],"instructions":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, вытянув руки.","Повторите необходимое количество повторений."]},
{"source_key":"e13","name":"Жим гантелей лёжа","muscle_group":"Грудь","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e14","name":"Жим гантелей под углом","muscle_group":"Грудь","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e15","name":"Отжимания","muscle_group":"Грудь","equipment":"вес тела","measure":"reps","bodyweight":true,"aliases":["Отжимания","push-up"],"instructions":["Начните с позиции высокой планки, расставив руки чуть шире плеч и поставив ноги вместе.","Напрягите корпус и опустите тело к земле, сгибая локти, удерживая тело на прямой линии.","Сделайте паузу на мгновение, когда ваша грудь окажется чуть выше земли, затем вернитесь в исходное положение, выпрямляя руки.","Повторите необходимое количество повторений."]},
{"source_key":"e16","name":"Жим гантелей сидя","muscle_group":"Плечи","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":[],"instructions":[]},
{"source_key":"e17","name":"Махи в стороны","muscle_group":"Плечи","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":["разводка стоя","Подъём гантелей в стороны","dumbbell lateral raise"],"instructions":["Встаньте, ноги на ширине плеч, возьмите в каждую руку по гантели ладонями к телу.","Держите спину прямо и задействуйте корпус.","Поднимите руки в стороны до тех пор, пока они не станут параллельны полу, сохраняя небольшой изгиб в локтях.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."]},
{"source_key":"e18","name":"Сгибания на бицепс с гантелями","muscle_group":"Руки","equipment":"гантели","measure":"reps","bodyweight":false,"aliases":["бицуха","бицепс","Сгибание рук с гантелями","dumbbell biceps curl"],"instructions":["Встаньте прямо, взяв в каждую руку по гантели, ладони направлены вперед, руки полностью выпрямлены.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать гири до тех пор, пока ваши бицепсы полностью не сократятся и гантели не окажутся на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать гантели обратно в исходное положение.","Повторите необходимое количество повторений."]},
