{"source_key":"e80","name":"Тяга верхнего блока параллельным хватом","muscle_group":"Спина","equipment":"блок","measure":"reps","bodyweight":false,"aliases":["Тяга верхнего блока параллельным хватом","twin handle parallel grip lat pulldown"],"instructions":["Отрегулируйте высоту сиденья и расположитесь лицом к канатной машине.","Возьмитесь за рукоятки хватом сверху, руки на ширине плеч.","Сядьте и расположите бедра под подушечками для бедер, удерживая ступни ровно на полу.","Слегка откиньтесь назад и держите грудь вверх, сохраняя нейтральное положение позвоночника.","Потяните ручки вниз к верхней части груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, чувствуя сокращение широчайших мышц.","Медленно отпустите ручки и вернитесь в исходное положение.","Повторите необходимое количество повторений."]}
]$catalog$::jsonb) as catalog(source_key text, name text, muscle_group text, equipment text, measure text, bodyweight boolean, aliases text[], instructions text[]);

insert into public.exercises (workspace_id, source_key, name, muscle_group, equipment, measure, bodyweight, aliases, instructions, created_by)
select w.id, c.source_key, c.name, c.muscle_group, c.equipment, c.measure, c.bodyweight, c.aliases, c.instructions, w.owner_user_id
from public.trainer_workspaces w cross join private.exercise_catalog c;

commit;
